{
  "title": "The Gilded Escape",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The heroes approach the ruined city.",
      "visual_description": "A crumbling royal city looms under a smoky sky, its outer walls broken, old royal banners tattered on spires.",
      "characters": ["Aric", "Mira", "Thorn"]
    },
    {
      "scene_number": 2,
      "caption": "Frightened townspeople warn them of danger.",
      "visual_description": "A huddled group of dirty townspeople gestures nervously toward the castle, one woman clutching a child.",
      "characters": ["Aric", "Mira", "Thorn", "Elara", "Old Man Heston"]
    },
    {
      "scene_number": 3,
      "caption": "Armored patrols march through the outer square.",
      "visual_description": "A squad of six armored soldiers in black and silver, their captain barking orders, torches flickering.",
      "characters": ["Captain Voss", "Soldier 1", "Soldier 2", "Soldier 3", "Soldier 4", "Soldier 5"]
    },
    {
      "scene_number": 4,
      "caption": "The heroes sneak past the patrols toward the castle gates.",
      "visual_description": "Moonlit shadows as Aric, Mira, and Thorn press against a wall, the massive iron castle gates in view.",
      "characters": ["Aric", "Mira", "Thorn"]
    },
    {
      "scene_number": 5,
      "caption": "A magic door appears in the outer wall.",
      "visual_description": "A shimmering, rune-covered door materializes between two cracked pillars, glowing softly.",
      "characters": ["Aric", "Mira"]
    },
    {
      "scene_number": 6,
      "caption": "Mira deciphers the door's riddle.",
      "visual_description": "Mira runs her fingers over the runes, her eyes scanning as Aric guards the alley.",
      "characters": ["Aric", "Mira"]
    },
    {
      "scene_number": 7,
      "caption": "The door swings open into a cursed tower.",
      "visual_description": "A spiral staircase ascending into darkness, cobwebs and faint blue light, a disembodied whisper echoes.",
      "characters": ["Aric", "Mira", "Thorn"]
    },
    {
      "scene_number": 8,
      "caption": "Thorn hears a rumor of a dragon in the tower.",
      "visual_description": "Thorn cups his ear, a ghostly figure in the wall whispers of a sleeping dragon above.",
      "characters": ["Thorn", "Ghostly Whisperer"]
    },
    {
      "scene_number": 9,
      "caption": "A trap door opens beneath Mira.",
      "visual_description": "Mira falls through a hidden trap, landing in a dusty chamber full of golden treasures.",
      "characters": ["Mira"]
    },
    {
      "scene_number": 10,
      "caption": "Aric and Thorn rescue Mira from the treasure room.",
      "visual_description": "Aric lowers a rope as Thorn holds off animated golden statues that lurch to life.",
      "characters": ["Aric", "Mira", "Thorn", "Golden Statue 1", "Golden Statue 2"]
    },
    {
      "scene_number": 11,
      "caption": "They find the prisoner in the tower's highest cell.",
      "visual_description": "A barred cell with a frail prisoner, Princess Lira, her dress torn, face smudged.",
      "characters": ["Aric", "Mira", "Thorn", "Princess Lira"]
    },
    {
      "scene_number": 12,
      "caption": "Armored patrols block the stairway down.",
      "visual_description": "Soldiers clatter up the stairs, swords drawn, Captain Voss leading.",
      "characters": ["Captain Voss", "Soldier 1", "Soldier 2", "Soldier 3", "Soldier 4", "Soldier 5", "Aric", "Mira", "Thorn", "Princess Lira"]
    },
    {
      "scene_number": 13,
      "caption": "Aric fights the patrol while Mira and Thorn flee with Lira.",
      "visual_description": "Clashing swords on the narrow stairs, sparks fly, Aric parries two soldiers.",
      "characters": ["Aric", "Captain Voss", "Soldier 1", "Soldier 2"]
    },
    {
      "scene_number": 14,
      "caption": "The dragon awakens in the tower depths.",
      "visual_description": "A massive red eye opens in the darkness below, smoke rising, a low growl shakes the stone.",
      "characters": ["Dragon"]
    },
    {
      "scene_number": 15,
      "caption": "The group races across the castle ramparts.",
      "visual_description": "Moonlit battlements, flaming arrows from patrols below, the dragon's roar behind them.",
      "characters": ["Aric", "Mira", "Thorn", "Princess Lira"]
    },
    {
      "scene_number": 16,
      "caption": "They reach the final escape bridge.",
      "visual_description": "A crumbling stone bridge over a chasm, torches on the far side, the dragon bursts through a wall behind them.",
      "characters": ["Aric", "Mira", "Thorn", "Princess Lira", "Dragon"]
    },
    {
      "scene_number": 17,
      "caption": "Aric holds the bridge as the others cross.",
      "visual_description": "Aric stands at the bridge's midpoint, sword raised, as the dragon charges, jaws open.",
      "characters": ["Aric", "Dragon"]
    },
    {
      "scene_number": 18,
      "caption": "The bridge collapses, but the heroes escape.",
      "visual_description": "The bridge crumbles, Aric leaps to safety as the dragon falls into the chasm, the group on the far side, dawn breaking.",
      "characters": ["Aric", "Mira", "Thorn", "Princess Lira"]
    }
  ]
}

